// Late-bound APNs handles. Constructed inside `app.whenReady()` (because
// the token store needs `app.getPath('userData')`). Kept at module scope
// so the ApprovalService can read them via the `getApnsPusher` /
// `getApnsTokenStore` deps it's constructed with.
let bridgeApnsTokenStoreRef: BridgeApnsTokenStore | null = null
let bridgeApnsPusherRef: BridgeApnsPusher | null = null
let remoteAttentionApnsFanoutRef: RemoteAttentionApnsFanout | null = null
/** The Mac's 32-byte identity seed (set when the bridge identity loads). Used to
 * seal per-device ENCRYPTED rich push content + to publish the Mac's agreement
 * public key at device registration. Null until the bridge identity loads. */
let macIdentitySeedRef: Buffer | null = null

// Phase B3: late-bound ApprovalService. Owns the five pending-approval
// registries + the scheduled-timeout integration + the APNs wake-push
// fan-out. Stays null until whenReady constructs it; the module-level
// `scheduleApprovalTimeout` / `notifyPairedDevicesOfApproval` /
// `workspaceIdForApprovalPush` helpers are thin proxies that no-op
// until the service is ready.
let approvalService: ApprovalService | null = null

// Phase F3: late-bound RunCoordinator ref. The coordinator is
// constructed in whenReady (it needs the in-scope `providerAdapters`
// + the inline helper functions for normalize / preflight / etc.),
// but exposed at module scope so the agent-driven sub-thread
// delegation path (MCP tool `delegate_to_subthread`, executed from
// the top-level `executeGeminiMcpTool`) can fire-and-forget a run on
// the newly-created sub-thread without going through the renderer.
// Stays null until whenReady; the consumer null-checks.
let runCoordinatorRef: RunCoordinator | null = null
// Provider auto-failover (quota-wall kill-switch) — module-scope state.
// `dispatchRunWithProviderPauseRef` is assigned inside whenReady so the
// failover orchestrator (module scope) can re-dispatch through the same
// pause/reroute seam the renderer + bridge use.
let dispatchRunWithProviderPauseRef:
  | ((
      payload: AgentRunPayload,
      event: { sender: Electron.WebContents }
    ) => Promise<{ dispatched: boolean; appRunId: string }>)
  | null = null
const quotaWallSignalByRun = new Map<string, { provider: ProviderId; resetHintAt?: string }>()
const failoverSnapshotByRun = new Map<string, FailoverRunSnapshot>()
// A failover-rerouted run is dispatched MAIN-side with a fresh runId — the renderer
// never registers an ActiveRunContext carrying scheduledTaskId for it, so its per-run
// exit can't mark the scheduled task terminal (it would stay stuck 'running'). Bridge
// it main-side: remember newRunId -> scheduledTaskId on reroute, mark terminal in
// sendAgentCompatExit. Mirrors the ensemble fix (bb6b3aa8).
const scheduledTaskIdByFailoverRun = new Map<string, string>()

// Stage 0b-completion: a SOLO scheduled run is normally marked terminal by the
// renderer; if the renderer closes mid-run the task wedges (the stall reconciler
// is the only backstop, 6h later). Bridge it main-side too: remember
// appRunId -> scheduledTaskId at dispatch, mark terminal in sendAgentCompatExit.
// Idempotent vs the renderer mark (updateScheduledTask's transition guard).
const scheduledTaskIdBySoloRun = new Map<string, string>()

// Stage 0b-dispatch — composerServiceRef lets the scheduler compose a run from
// MAIN (the ComposerService is constructed later, in whenReady); headlessRunSender
// stands in for event.sender when there is NO window to stream to. The run-loop
// streams deltas through `.send` (guarded by `.isDestroyed()`) and reads `.id`;
// with no window nothing listens, but disk persistence (appendRunEvent, the
// terminal scheduled-task mark) is sender-INDEPENDENT, so the run still completes
// and is recorded. Every other access resolves to a no-op fn (defensive — the
// dispatch path touches only id/isDestroyed/send).
let composerServiceRef: ComposerService | null = null
const headlessRunSender = new Proxy(
  {},
  {
    get: (_target, prop) => {
      if (prop === 'isDestroyed') return () => false
      if (prop === 'id') return -1
      return () => undefined
    }
  }
) as unknown as Electron.WebContents

// Per-occurrence mid-run BUDGET KILL (WorkflowLimits enforcement). SOLO scheduled
// runs only — ensemble is OUT (no per-participant scheduledTaskId; shared round
// accounting; never failed over). abort = cancelProviderRun (RC1: NOT
// runManager.cancel, which skips Codex's turn/interrupt RPC). The task is marked
// failed at the kill DECISION (triggerKill), not on exit — the default Claude SDK
// abort never reaches sendAgentCompatExit, and the mark must beat the renderer's
// run-end mark. Timers .unref() so an armed kill never holds the loop open at quit.
// Stage 1 slice 3 — resolve a scheduled task's workflow execution id (the run
// ledger's per-execution file key) + its workflowId. undefined for an ad-hoc
// (non-workflow) scheduled task → the caller skips the ledger append (the run
// ledger is workflow-scoped). Same lookup the budget registration uses.
function resolveWorkflowExecutionForTask(
  scheduledTaskId: string | undefined
): { workflowExecutionId: string; workflowId: string } | undefined {
  if (!scheduledTaskId) return undefined
  const task = AppStore.getScheduledTasks().find((t) => t.id === scheduledTaskId)
  if (!task?.workflowExecutionId || !task.workflowId) return undefined
  return { workflowExecutionId: task.workflowExecutionId, workflowId: task.workflowId }
}

// Slice 3 (a) — record a budget breach into the durable run ledger. Best-effort
// (a ledger write must never break the kill / terminal path).
function recordWorkflowBudgetBreach(
  scheduledTaskId: string,
  runId: string,
  breach: { kind: 'tokens' | 'cost' | 'wallclock'; limit: number; observed: number }
): void {
  const resolved = resolveWorkflowExecutionForTask(scheduledTaskId)
  if (!resolved) return
  try {
    AppStore.appendWorkflowRunEvent({
      ...resolved,
      kind: 'budget_breach',
      scheduledTaskId,
      runId,
      breach: { kind: breach.kind, limit: breach.limit, observed: breach.observed }
    })
  } catch (e) {
    console.error('Failed to record workflow budget_breach ledger event', e)
  }
}

// Slice 3 (b) — harvest a finished scheduled run's tokens/cost/duration into the
// run ledger as a forensic 'harvested' annotation (does NOT change lifecycle
// status — it rides alongside the terminal lifecycle event the sync path already
// wrote). `route` is the run state carried into sendAgentCompatExit (tokenUsage +
// startedAt). Best-effort; skipped for a non-workflow task or when there's nothing
// to record (no token signal AND no start time — e.g. a grok/cursor mid-run exit).
function recordWorkflowRunHarvest(scheduledTaskId: string, runId: string, route: unknown): void {
  const task = AppStore.getScheduledTasks().find((t) => t.id === scheduledTaskId)
  if (!task?.workflowExecutionId || !task.workflowId) return
  const usage = (route as { tokenUsage?: { total_tokens?: number; total_cost_usd?: number } } | null)
    ?.tokenUsage
  const tokens = typeof usage?.total_tokens === 'number' ? usage.total_tokens : undefined
  const costUsd = typeof usage?.total_cost_usd === 'number' ? usage.total_cost_usd : undefined
  // durationMs: prefer the provider stream's startedAt (most precise), else the
  // task's into-running stamp (runningSince → firedAt). The fallback makes duration
  // UNIVERSAL — recorded even for providers / exit paths that pass a BARE route with
  // no stream startedAt (Ollama; every early-error / preflight / setup exit). tokens
  // and costUsd stay best-effort: absent for Ollama (usage rides the result line,
  // not the route) and for early errors (no usage produced yet) — by design.
  const routeStartedAt = (route as { startedAt?: number } | null)?.startedAt
  const startedAtMs =
    typeof routeStartedAt === 'number'
      ? routeStartedAt
      : task.runningSince
        ? Date.parse(task.runningSince)
        : task.firedAt
          ? Date.parse(task.firedAt)
          : Number.NaN
  const durationMs = Number.isFinite(startedAtMs) ? Math.max(0, Date.now() - startedAtMs) : undefined
  if (tokens === undefined && costUsd === undefined && durationMs === undefined) return
  try {
    AppStore.appendWorkflowRunEvent({
      workflowExecutionId: task.workflowExecutionId,
      workflowId: task.workflowId,
      kind: 'harvested',
      scheduledTaskId,
      runId,
      ...(tokens !== undefined ? { tokens } : {}),
      ...(costUsd !== undefined ? { costUsd } : {}),
      ...(durationMs !== undefined ? { durationMs } : {})
    })
  } catch (e) {
    console.error('Failed to record workflow run harvest ledger event', e)
  }
}

const workflowBudgetRegistry = new WorkflowBudgetRegistry({
  abort: (provider, runId) => {
    void cancelProviderRun(provider, runId)
  },
  markTaskFailed: (scheduledTaskId, lastError) => {
    AppStore.updateScheduledTask(scheduledTaskId, {
      status: 'failed',
      completedAt: new Date().toISOString(),
      lastError
    })
  },
  now: () => Date.now(),
  setTimer: (fn, ms) => {
    const handle = setTimeout(fn, ms)
    handle.unref?.()
    return handle
  },
  clearTimer: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
  onEvent: (event) => {
    if (event.kind === 'killed') {
      console.warn(
        `[workflow-budget] killing run ${event.runId} (${event.provider}, task ${event.scheduledTaskId}): ${event.breach.kind} budget exceeded`
      )
      recordWorkflowBudgetBreach(event.scheduledTaskId, event.runId, event.breach)
    } else if (event.kind === 'task-failed' && event.breach) {
      // POST-HOC grok/cursor overage (onTerminalUsage): no 'killed' event fired for
      // it, so record the breach here so the ledger still captures it.
      recordWorkflowBudgetBreach(event.scheduledTaskId, event.runId, event.breach)
    }
  }
})

/**
 * Re-derive + re-sign a CAPPED, non-escalating permission posture for an
 * auto-failover reroute TARGET. Runs at the dispatch seam after
 * applyReroutePlanToPayload cleared the cross-provider posture, before
 * normalize would downgrade it. Mutates routedPayload in place. Scoped to
 * failover runs so manual reroutes keep their existing fail-closed behavior.
 */
function applyFailoverReroutePosture(
  routedPayload: AgentRunPayload,
  originalPayload: AgentRunPayload
): void {
  const target = routedPayload.provider
  // Auto-failover is a non-escalating safety path: cap a reroute TARGETING Ollama
  // to plan/read-only regardless of the origin posture. (This is deliberately
  // MORE conservative than an interactive Ollama run, which now honors the user's
  // picked role — see runOllamaProviderAdapter — because a machine-initiated
  // failover must never silently gain write/shell authority the user didn't pick
  // for this target.)
  if (target === 'ollama') routedPayload.approvalMode = 'plan'
  const cappedMode = routedPayload.approvalMode
  const originalPresetId = originalPayload.effectivePermissions?.presetId
  const presetId = reroutePresetId(cappedMode, originalPresetId, target)
  if (!isNonEscalatingPreset(presetId, originalPresetId)) {
    // Would escalate ⇒ bail; normalize then fails it closed to read-only.
    return
  }
  let effective: EffectiveRunPermissions | undefined
  if (presetId && !(routedPayload.scope === 'global' && cappedMode !== 'plan')) {
    effective = resolveEffectiveRunPermissions({
      provider: target,
      workspacePath: routedPayload.scope === 'global' ? undefined : routedPayload.workspace,
      settings: AppStore.getSettings(),
      presetId
    })
  }
  routedPayload.effectivePermissions = effective
  routedPayload.effectivePermissionsSignature = signRunPosture(
    routedPayload.approvalMode,
    effective,
    runPostureContextFromPayload(routedPayload)
  )
}

/** Snapshot a dispatched request so a future quota wall can re-run it faithfully. */
function captureFailoverSnapshot(payload: AgentRunPayload): FailoverRunSnapshot {
  return {
    provider: payload.provider,
    scope: payload.scope,
    workspace: payload.workspace,
    prompt: payload.prompt,
    activeGoal: payload.activeGoal,
    appChatId: payload.appChatId,
    approvalMode: payload.approvalMode,
    workflowMode: payload.workflowMode,
    effectivePermissions: payload.effectivePermissions,
    model: payload.model,
    reasoningEffort: payload.reasoningEffort,
    serviceTier: payload.serviceTier,
    claudeReasoningEffort: payload.claudeReasoningEffort,
    claudeFastMode: payload.claudeFastMode,
    kimiThinking: payload.kimiThinking,
    runtimeProfileId: payload.runtimeProfileId,
    geminiAuthProfileId: payload.geminiAuthProfileId,
    failoverHopCount: payload.failoverHopCount,
    // routedPayload is the PRE-normalize raw renderer payload, so scheduledTaskId
    // is still structurally present (normalizeAgentRunPayload strips it).
    scheduledTaskId: (payload as { scheduledTaskId?: string }).scheduledTaskId
  }
}

/** Gate + fire an auto-failover on a terminal failed exit; prune per-run state. */
function maybeTriggerProviderAutoFailover(
  appRunId: string,
  provider: ProviderId,
  appChatId: string | undefined,
  exitCode: number | null
): void {
  const failed = (exitCode ?? -1) !== 0
  const signal = quotaWallSignalByRun.get(appRunId)
  const snapshot = failoverSnapshotByRun.get(appRunId)
  quotaWallSignalByRun.delete(appRunId)
  failoverSnapshotByRun.delete(appRunId)
  if (!failed) return
  if (!signal || AppStore.getSettings().autoFailoverEnabled !== true) return
  // Dedup is via signal consumption above (signal+snapshot are deleted before
  // we fire), so a second terminal exit for the same run finds no signal and
  // no-ops — no separate triggered-ids set needed.
  // Ensemble participant runs share per-round accounting — never fail them over.
  const chat = appChatId ? AppStore.getChat(appChatId) : undefined
  if (chat?.chatKind === 'ensemble') return
  void triggerProviderAutoFailover(appRunId, provider, appChatId, signal.resetHintAt, snapshot)
}

/** Wire the failover orchestrator to live main-process dependencies. */
async function triggerProviderAutoFailover(
  failedRunId: string,
  failedProvider: ProviderId,
  appChatId: string | undefined,
  resetHintAt: string | undefined,
  snapshot: FailoverRunSnapshot | undefined
): Promise<void> {
  const dispatchRef = dispatchRunWithProviderPauseRef
  if (!dispatchRef) return
  const sender =
    mainWindow?.webContents && !mainWindow.webContents.isDestroyed()
      ? mainWindow.webContents
      : createHeadlessRunSender()
  try {
    const failoverResult = await runProviderAutoFailover(
      {
        getSettings: () => AppStore.getSettings(),
        updateSettings: (partial) => AppStore.updateSettings(partial),
        availableProviders: () => selectableProviderIds(),
        isPaused: (candidate) => isProviderPaused(AppStore.getSettings(), candidate),
        signPosture: (mode, eff, ctx) => signRunPosture(mode, eff, ctx),
        makeRunId: (candidate) => createFallbackRunId(candidate),
        dispatch: (payload) => dispatchRef(payload, { sender }),
        notify: (notice) => emitAutoFailoverNotice(notice)
      },
      { failedRunId, failedProvider, appChatId, snapshot, resetHintAt }
    )
    // Carry the scheduled-task linkage onto the rerouted run so its main-side exit
    // marks the task terminal (the renderer never sees this run).
    if (failoverResult.ok && failoverResult.newRunId && snapshot?.scheduledTaskId) {
      scheduledTaskIdByFailoverRun.set(failoverResult.newRunId, snapshot.scheduledTaskId)
    }
  } catch (error) {
    console.warn('[auto-failover] orchestration failed', error)
  }
}

function emitAutoFailoverNotice(notice: AutoFailoverNotice): void {
  if (notice.kind === 'rerouted') {
    console.info(
      `[auto-failover] ${notice.failedProvider} quota wall → rerouted to ${notice.target} (resets ${notice.until}); new run ${notice.newRunId}`
    )
  } else {
    console.warn(`[auto-failover] ${notice.kind} for ${notice.failedProvider}`)
  }
}
let ensembleOrchestratorRef: EnsembleOrchestrator | null = null
// Scheduled ENSEMBLE occurrences carry no per-participant scheduledTaskId, so the
// renderer's per-run exit (which marks single-provider scheduled tasks terminal)
// never fires for them — the task would stay stuck 'running' forever. Bridge it
// main-side: capture roundId -> scheduledTaskId at dispatch, mark the task in the
// round-settle hook (completeSessionCheckpoint), then forget it.
const scheduledTaskIdByEnsembleRound = new Map<string, string>()
let wakeupTimerServiceRef: WakeupTimerService | null = null
let sessionCheckpointStoreRef: SessionCheckpointStore | null = null
let updateServiceRef: UpdateService | null = null
let managedPolicySnapshotForDiagnostics: (() => Record<string, unknown> | undefined) | null = null
let managedUserMcpLaunchAllowlistPolicy: (() => UserMcpLaunchAllowlistPolicy | undefined) | null =
  null
let pluginHostRef: PluginHost | null = null
let pluginContributionManagerRef: PluginContributionManager | null = null
let localServersServiceRef: LocalServersService | null = null
/** Processes TaskWraith spawns for agent tool calls — tracked so the Local
 * Servers panel can attribute them and group-kill them cleanly. */
const spawnRegistry = new SpawnRegistry()

function validateUserMcpPluginProvenance(server: UserMcpServerConfig): string | undefined {
  if (!server.pluginProvenance) return undefined
  const result = pluginHostRef?.validateMcpServerProvenance(server.pluginProvenance)
  if (!result) return 'plugin provenance validator is unavailable'
  return result.ok ? undefined : result.reason || 'plugin provenance is not current'
}

const BACKGROUND_PROCESS_LOG_LIMIT = 500_000
const BACKGROUND_PROCESS_ENTRY_LIMIT = 80

type BackgroundProcessStreamName = 'stdout' | 'stderr' | 'both'
type BackgroundProcessSignalName = 'SIGTERM' | 'SIGKILL'

interface BackgroundProcessEntry {
  processId: string
  appChatId: string
  name?: string
  command: string
  cwd: string
  child: ChildProcess
  pid?: number
  startedAt: string
  endedAt?: string
  exitCode?: number | null
  signal?: NodeJS.Signals | null
  error?: string
  stdout: string
  stderr: string
  stdoutBase: number
  stderrBase: number
  stdoutLength: number
  stderrLength: number
}

function packageScriptsForCwd(cwd: string): Record<string, unknown> | null {
  try {
    const packageJsonPath = join(cwd, 'package.json')
    if (!fsSync.existsSync(packageJsonPath)) return null
    const parsed = JSON.parse(fsSync.readFileSync(packageJsonPath, 'utf8')) as {
      scripts?: unknown
    }
    return parsed.scripts && typeof parsed.scripts === 'object'
      ? (parsed.scripts as Record<string, unknown>)
      : null
  } catch {
    return null
  }
}

interface HostCommandRunOptions {
  timeoutMs?: number
  releaseApproval?: ReleaseCommandCheckOptions
}

type HostCommandRunArgument = number | HostCommandRunOptions

class BackgroundProcessRegistry {
  private entries = new Map<string, BackgroundProcessEntry>()

  async start(
    command: string,
    cwd: string,
    options: {
      appChatId: string
      name?: string
      initialWaitMs: number
      maxInitialChars: number
      releaseApproval?: ReleaseCommandCheckOptions
    }
  ): Promise<Record<string, unknown>> {
    const startedAt = new Date().toISOString()
    const processId = `bg-${Date.now()}-${randomBytes(4).toString('hex')}`
    const blockedReleaseCommand =
      releaseCommandBlockReason(command, options.releaseApproval) ||
      releasePackageScriptBlockReason(command, packageScriptsForCwd(cwd), options.releaseApproval)
    if (blockedReleaseCommand) {
      return {
        ok: false,
        processId,
        command,
        cwd,
        startedAt,
        error: blockedReleaseCommand
      }
    }
    const shellCommand =
      process.env.SHELL || (process.platform === 'win32' ? 'powershell.exe' : '/bin/zsh')
    const shellArgs =
      process.platform === 'win32' ? ['-NoProfile', '-Command', command] : ['-lc', command]

    let child: ChildProcess
    try {
      child = spawn(shellCommand, shellArgs, {
        cwd,
        shell: false,
        detached: true,
        windowsHide: true,
        env: createCliEnv({ FORCE_COLOR: '0', NO_COLOR: '1' }, shellCommand)
      })
    } catch (error) {
      return {
        ok: false,
        processId,
        command,
        cwd,
        startedAt,
        error: error instanceof Error ? error.message : String(error)
      }
    }

    const entry: BackgroundProcessEntry = {
      processId,
      appChatId: options.appChatId,
      name: options.name,
      command,
      cwd,
      child,
      pid: child.pid,
      startedAt,
      stdout: '',
      stderr: '',
      stdoutBase: 0,
      stderrBase: 0,
      stdoutLength: 0,
      stderrLength: 0
    }
    this.entries.set(processId, entry)
    this.prune()

    if (child.pid) {
      spawnRegistry.track({
        pid: child.pid,
        pgid: child.pid,
        startedAt,
        workspacePath: cwd
      })
    }

    child.stdout?.on('data', (chunk) => this.append(entry, 'stdout', chunk.toString()))
    child.stderr?.on('data', (chunk) => this.append(entry, 'stderr', chunk.toString()))
    child.on('error', (error) => {
      entry.error = error.message
    })
    child.on('close', (code, signal) => {
      entry.exitCode = code
      entry.signal = signal
      entry.endedAt = new Date().toISOString()
      if (entry.pid) spawnRegistry.untrack(entry.pid)
    })

    if (options.initialWaitMs > 0) {
      await new Promise((resolveWait) => setTimeout(resolveWait, options.initialWaitMs))
    }

    return this.read(processId, {
      appChatId: options.appChatId,
      stdoutOffset: 0,
      stderrOffset: 0,
      maxChars: options.maxInitialChars,
      stream: 'both'
    })
  }

  list(filter: { appChatId: string }): Record<string, unknown> {
    const processes = [...this.entries.values()]
      .filter((entry) => entry.appChatId === filter.appChatId)
      .sort((a, b) => b.startedAt.localeCompare(a.startedAt))
      .map((entry) => this.summary(entry))
    return { ok: true, count: processes.length, processes }
  }

  read(
    processId: string,
    options: {
      appChatId: string
      stdoutOffset?: number
      stderrOffset?: number
      maxChars: number
      stream: BackgroundProcessStreamName
    }
  ): Record<string, unknown> {
    const entry = this.entryFor(processId, options.appChatId)
    if (!entry) return { ok: false, processId, error: 'Background process not found for this chat.' }
    const stdout =
      options.stream === 'stdout' || options.stream === 'both'
        ? this.readStream(entry, 'stdout', options.stdoutOffset, options.maxChars)
        : undefined
    const stderr =
      options.stream === 'stderr' || options.stream === 'both'
        ? this.readStream(entry, 'stderr', options.stderrOffset, options.maxChars)
        : undefined
    return {
      ok: true,
      ...this.summary(entry),
      stdout,
      stderr
    }
  }

  async kill(
    processId: string,
    options: { appChatId: string; signal: BackgroundProcessSignalName }
  ): Promise<Record<string, unknown>> {
    const entry = this.entryFor(processId, options.appChatId)
    if (!entry) return { ok: false, processId, error: 'Background process not found for this chat.' }
    if (entry.endedAt) {
      return { ok: true, alreadyExited: true, ...this.summary(entry) }
    }
    try {
      if (entry.pid) {
        try {
          process.kill(-entry.pid, options.signal)
        } catch {
          entry.child.kill(options.signal)
        }
      } else {
        entry.child.kill(options.signal)
      }
      return { ok: true, signal: options.signal, ...this.summary(entry) }
    } catch (error) {
      return {
        ok: false,
        ...this.summary(entry),
        error: error instanceof Error ? error.message : String(error)
      }
    }
  }

  private append(entry: BackgroundProcessEntry, stream: 'stdout' | 'stderr', chunk: string): void {
    if (!chunk) return
    const bufferKey = stream
    const baseKey = stream === 'stdout' ? 'stdoutBase' : 'stderrBase'
    const lengthKey = stream === 'stdout' ? 'stdoutLength' : 'stderrLength'
    entry[bufferKey] += chunk
    entry[lengthKey] += chunk.length
    if (entry[bufferKey].length > BACKGROUND_PROCESS_LOG_LIMIT) {
      entry[bufferKey] = entry[bufferKey].slice(-BACKGROUND_PROCESS_LOG_LIMIT)
      entry[baseKey] = entry[lengthKey] - entry[bufferKey].length
    }
  }

  private readStream(
    entry: BackgroundProcessEntry,
    stream: 'stdout' | 'stderr',
    offset: number | undefined,
    maxChars: number
  ): Record<string, unknown> {
    const buffer = entry[stream]
    const base = stream === 'stdout' ? entry.stdoutBase : entry.stderrBase
    const total = stream === 'stdout' ? entry.stdoutLength : entry.stderrLength
    const requestedOffset = typeof offset === 'number' ? offset : Math.max(base, total - maxChars)
    const startOffset = Math.max(base, Math.min(total, requestedOffset))
    const startIndex = Math.max(0, startOffset - base)
    const text = buffer.slice(startIndex, startIndex + maxChars)
    const cursor = startOffset + text.length
    return {
      text,
      offset: startOffset,
      cursor,
      length: total,
      truncatedBefore: requestedOffset < base,
      truncatedAfter: cursor < total
    }
  }

  private summary(entry: BackgroundProcessEntry): Record<string, unknown> {
    return {
      processId: entry.processId,
      name: entry.name,
      command: entry.command.length > 500 ? `${entry.command.slice(0, 500)}...` : entry.command,
      cwd: entry.cwd,
      pid: entry.pid,
      running: !entry.endedAt,
      startedAt: entry.startedAt,
      endedAt: entry.endedAt,
      exitCode: entry.exitCode,
      signal: entry.signal,
      error: entry.error,
      stdoutLength: entry.stdoutLength,
      stderrLength: entry.stderrLength
    }
  }

  private entryFor(processId: string, appChatId: string): BackgroundProcessEntry | undefined {
    const entry = this.entries.get(processId)
    if (!entry || entry.appChatId !== appChatId) return undefined
    return entry
  }

  private prune(): void {
    if (this.entries.size <= BACKGROUND_PROCESS_ENTRY_LIMIT) return
    const entries = [...this.entries.values()].sort((a, b) => a.startedAt.localeCompare(b.startedAt))
    for (const entry of entries) {
      if (this.entries.size <= BACKGROUND_PROCESS_ENTRY_LIMIT) break
      if (!entry.endedAt) continue
      this.entries.delete(entry.processId)
    }
  }
}

const backgroundProcessRegistry = new BackgroundProcessRegistry()
let faviconServiceRef: FaviconService | null = null
