// TaskWraith Canvas (P0) — exclusive preview/runtime surface. CanvasService owns
// the live session registry + drivers; the canvas_* MCP tools route through
// canvasToolExecutors (see executeGeminiMcpTool). Persistence + audit events live
// in a self-contained CanvasStore (own atomic JSON) and broadcast to the renderer
// as 'canvas-event'. The web driver opens one sandboxed BrowserWindow per session.
// Renderer-pane embed: hosts a canvas as a WebContentsView floated over the pane
// (lazily reads mainWindow, which is assigned later, so the closure is safe here).
const canvasEmbedController = new CanvasEmbedController({
  getParentWindow: () =>
    mainWindow && !mainWindow.isDestroyed() ? asEmbedParent(mainWindow) : null,
  createView: createElectronEmbedView
})
// One shared offscreen image engine for both the image_* tools and the canvas
// `html` driver (canvas_render_html) — its renderHtmlToPng is the hardened,
// JS-off, egress-cut rasterizer.
const offscreenImageEngine = createNativeImageEngine()
const CANVAS_HTML_RENDER_TIMEOUT_MS = 15_000
const canvasService = new CanvasService({
  createDriver: (
    kind: CanvasDriverKind,
    sessionId: string,
    opts?: {
      embedded?: boolean
      initialSketchDocument?: CanvasSketchDocument
      onSketchDocumentChange?: (document: CanvasSketchDocument) => void
    }
  ) => {
    if (kind === 'device') return new CanvasDeviceDriver(sessionId)
    if (kind === 'html') {
      return new CanvasRenderDriver(sessionId, {
        render: (html, width, height) =>
          offscreenImageEngine.renderHtmlToPng(html, width, height, CANVAS_HTML_RENDER_TIMEOUT_MS)
      })
    }
    if (kind === 'image') {
      return new CanvasImageDriver(sessionId, {
        // Resolve through the asset store's realpath jail (sha + mime->ext
        // whitelist) and decode via nativeImage — the agent can only view an
        // EXISTING content-addressed attachment, never an arbitrary file.
        load: async (sha256, mimeType) => {
          const res = getTranscriptMediaAssetStore().read({ sha256, mimeType })
          if (!res.ok) throw new Error(`Image attachment unavailable (${res.reason}).`)
          // Pre-decode bomb guard: an 8MiB compressed PNG can declare a 20000x20000
          // bitmap (~1.6GB RGBA). Reject a too-large DECLARED size (cheap IHDR read)
          // before nativeImage allocates it. Non-PNG falls through to the post-decode
          // downscale below.
          const declared = readPngDimensions(res.buffer)
          if (declared.width * declared.height > CANVAS_IMAGE_MAX_DECODE_PIXELS) {
            throw new Error('Image attachment is too large to preview.')
          }
          const img = nativeImage.createFromBuffer(res.buffer)
          if (img.isEmpty()) throw new Error('Attachment is not a decodable image.')
          // Post-decode: downscale an oversized image so the re-encoded PNG + base64
          // tool result stays bounded (also caps non-PNG inputs).
          const { width, height } = img.getSize()
          const fit = fitWithinMaxEdge(width, height)
          const out = fit.width !== width || fit.height !== height ? img.resize(fit) : img
          return out.toPNG()
        }
      })
    }
    if (kind === 'sketch') {
      return new CanvasSketchDriver(sessionId, {
        initialDocument: opts?.initialSketchDocument,
        onDocumentChange: opts?.onSketchDocumentChange
      })
    }
    if (kind === 'web') {
      return opts?.embedded
        ? new CanvasWebDriver(sessionId, {
            createSurface: canvasEmbedController.surfaceFor(sessionId)
          })
        : new CanvasWebDriver(sessionId)
    }
    throw new Error(`Canvas driver "${kind}" is not available in this build.`)
  },
  store: new CanvasStore(join(app.getPath('userData'), 'canvas')),
  uuid: () => randomUUID(),
  now: () => new Date().toISOString(),
  broadcast: (event: CanvasEventRecord) => {
    safeSendToWebContents(mainWindow, 'canvas-event', event)
  },
  logger: console
})
let canvasShutdownCloseAllInFlight: Promise<void> | null = null
