// M11 (1.0.7) — sticky AppWatch: per-chat remembered attachment snapshots,
// persisted so they survive an app restart. The pure store logic lives in
// `stickyAppWatch.ts`; here we hold the in-memory copy + its json file. Loaded
// lazily on first access; written best-effort on every change.
let stickyAppWatchStore: StickyAppWatchStore | null = null
function stickyAppWatchPath(): string {
  return join(app.getPath('userData'), 'sticky-appwatch.json')
}
async function loadStickyAppWatchStore(): Promise<StickyAppWatchStore> {
  if (stickyAppWatchStore) return stickyAppWatchStore
  const raw = await readJsonFile(stickyAppWatchPath())
  stickyAppWatchStore = normalizeStickyAppWatchStore(raw)
  return stickyAppWatchStore
}
async function persistStickyAppWatchStore(next: StickyAppWatchStore): Promise<void> {
  stickyAppWatchStore = next
  try {
    await writeJsonFile(stickyAppWatchPath(), next)
  } catch (err) {
    console.error('[sticky-appwatch] persist failed:', err)
  }
}

async function readJsonFile(filePath: string): Promise<any | null> {
  try {
    return JSON.parse(await fs.readFile(filePath, 'utf8'))
  } catch {
    return null
  }
}

async function writeJsonFile(filePath: string, value: any): Promise<void> {
  await fs.mkdir(dirname(filePath), { recursive: true })
  await fs.writeFile(filePath, `${JSON.stringify(value, null, 2)}\n`, 'utf8')
}


const backgroundSubThreadTranscripts = new Map<string, BackgroundSubThreadTranscriptState>()

/** iOS / bridge-initiated runs skip the renderer's `activeRunsRef`
 * registration, so provider compat lines would otherwise stream to
 * raw logs without persisting assistant text. Mirror the background
 * sub-thread transcript path: accumulate in main and flush to
 * `AppStore` so both Mac and phone snapshots stay live. */
type BridgeRunTranscriptState = {
  runId: string
  chatId: string
  provider: ProviderId
  promptMessageId: string
  assistantMessageId: string
  /** Tool-role sibling message carrying the run's ToolActivity stack. */
  toolMessageId: string
  startedAt: string
  content: string
  /** Ordered text/tool segments — interleaved like the desktop transcript
   * (text, tool burst, text, ...). Each part becomes its own message. */
  parts: Array<{
    id: string
    kind: 'text' | 'tools'
    content: string
    mediaRefs?: TranscriptMediaRef[]
    activities: ToolActivity[]
  }>
  streamBuffer?: string
  actualModel?: string
  modelLabel?: string
  providerSessionId?: string | null
  stats?: Record<string, unknown>
  status: 'running' | 'success' | 'failed'
  errorMessage?: string
  flushedOnce: boolean
  flushTimer?: NodeJS.Timeout
  /** Activities parsed from tool_use/tool_result compat events. */
  activities: ToolActivity[]
  /** Codex item id of the last appended content delta — a transition
   * marks a NEW agentMessage item, which the desktop separates with a
   * horizontal rule instead of letting bursts jam into one paragraph. */
  lastContentItemId?: string
  /** Captured before dispatch; diffed against a post-run snapshot at
   * finalize so bridge runs get run.runDiff like desktop runs do. */
  preSnapshot?: WorkspaceSnapshot
  workspacePath?: string
  /** Secondary-workspace grants: pre-run snapshots keyed by path. */
  extraPreSnapshots?: Record<string, WorkspaceSnapshot>
  extraWorkspacePaths?: string[]
  runDiff?: ChatRun['runDiff']
  runDiffByPath?: ChatRun['runDiffByPath']
}

const bridgeRunTranscripts = new Map<string, BridgeRunTranscriptState>()
let pushBridgeRunSnapshot: ((chat: ChatRecord) => void) | null = null
let pushBridgeRunTaskCardDelta: ((chatId: string) => void) | null = null
let pushRemoteThreadSnapshotForChat: ((chat: ChatRecord) => boolean) | null = null

/**
 * Phase B3 — thin proxy. Delegates to `approvalService.scheduleTimeout`
 * once the service is initialized. Kept at module scope so the
 * existing `pending*Approvals.set` call sites (which currently live
 * scattered through `runXxxProvider` functions) can call into the
 * service without changing every site to pass the service explicitly.
 */
function scheduleApprovalTimeout(args: {
  approvalId: string
  provider: ProviderId
  route?: AgentRunRoute | null
  isMainAuthority?: boolean
  kind?: string
}): void {
  approvalService?.scheduleTimeout(args)
}

/**
 * Live wrapper around `isUserAtDesktop` (pure logic in
 * `./ApnsIdleGate.ts`). Reads window-focus + system-idle from the
 * Electron runtime; the pure helper handles the env-var gating and
 * threshold logic. Fail-open: any throw returns false so an approval
 * push always goes out when in doubt.
 */
function userIsAtDesktop(): boolean {
  try {
    return pureIsUserAtDesktop({
      idleGateEnv: process.env.TASKWRAITH_APNS_IDLE_GATE,
      idleThresholdEnv: process.env.TASKWRAITH_APNS_IDLE_THRESHOLD_S,
      windowFocused: mainWindow?.isFocused?.() === true,
      idleSec:
        typeof powerMonitor?.getSystemIdleTime === 'function' ? powerMonitor.getSystemIdleTime() : 0
    })
  } catch {
    return false
  }
}

/**
 * Notify all paired iOS devices that an approval needs the user's
 * decision. Best-effort: fires per-device pushes via APNs in parallel,
 * doesn't block the caller, and silently no-ops when APNs is
 * un-configured (the factory returns `NoopApnsPusher` which doesn't
 * expose `pushApprovalToToken`).
 *
 * Token cleanup: when Apple replies with `Unregistered` /
 * `BadDeviceToken`, the device token is permanently invalid; we prune
 * it from `BridgeApnsTokenStore` so subsequent approvals don't waste a
 * request on a dead phone.
 *
 * Call sites: every place a `pendingXxxApprovals.set(approvalId, ...)`
 * happens — host commands, Codex permissions/elicitation/userInput,
 * Gemini tool prompts, Kimi prompts, main approval flow.
 */
/** Phase B3 — thin proxy. Delegates to `approvalService.notifyPairedDevices`
 * once the service is initialized; no-op until then. */
function notifyPairedDevicesOfApproval(args: {
  approvalId: string
  workspaceId: string | null
  threadId: string
  summary: string
}): void {
  if (remoteAttentionApnsFanoutRef) {
    remoteAttentionApnsFanoutRef.notify({
      reason: 'approval',
      workspaceId: args.workspaceId,
      threadId: args.threadId,
      approvalId: args.approvalId,
      projectionKind: 'MobileApprovalCard'
    })
    return
  }
  approvalService?.notifyPairedDevices({
    ...args,
    summary: 'Open TaskWraith to respond.'
  })
}

/**
 * Resolve a workspace path to its store-managed opaque `WorkspaceRecord.id`.
 * APNs payloads must never contain local filesystem paths, so unregistered
 * workspace paths deliberately omit the workspace id instead of falling back
 * to the path.
 */
function workspaceIdForApprovalPush(workspacePath: string | undefined): string | null {
  if (!workspacePath) return 'global'
  try {
    const record = findRegisteredWorkspace(workspacePath)
    return record?.id ?? null
  } catch {
    return null
  }
}

installIpcValidation(ipcMain)

// Ask Chromium to keep expensive renderer visuals on the GPU raster path where supported.
app.commandLine.appendSwitch('enable-gpu-rasterization')
app.commandLine.appendSwitch('enable-zero-copy')

// Register the twmedia:// scheme as privileged (standard + secure + stream) BEFORE
// app `ready` — required, and callable only once, pre-ready. `stream:true` lets
// <video>/<audio> stream + seek transcript media over HTTP Range (S0b). The handler
// itself is registered post-ready in app.whenReady() below.
protocol.registerSchemesAsPrivileged([TW_MEDIA_PRIVILEGE])

// Swallow EPIPE on stderr writes. Common cause: the BridgeDaemon
// subprocess streams chatty stderr lines through `onStderr → console.error`;
// when electron-vite's dev parent closes its pipe (e.g. during HMR teardown)
// the next write throws EPIPE and Electron surfaces it as a fatal
// JavaScript-error popup. Treating EPIPE as silent — we'd rather drop the
// log line than crash the app. Non-EPIPE errors still propagate.
process.stderr.on('error', (err) => {
  if ((err as NodeJS.ErrnoException).code === 'EPIPE') return
  throw err
})
process.stdout.on('error', (err) => {
  if ((err as NodeJS.ErrnoException).code === 'EPIPE') return
  throw err
})


function loadOrCreateExternalGrantSigningSecret(): Buffer {
  const secretPath = join(app.getPath('userData'), 'external-grant-signing-secret')
  try {
    const existing = fsSync.readFileSync(secretPath, 'utf-8').trim()
    if (/^[0-9a-f]{64}$/i.test(existing)) {
      return Buffer.from(existing, 'hex')
    }
  } catch {
    // Missing or unreadable secrets are replaced below.
  }

  const secret = randomBytes(32)
  fsSync.mkdirSync(dirname(secretPath), { recursive: true })
  fsSync.writeFileSync(secretPath, secret.toString('hex'), { mode: 0o600 })
  try {
    fsSync.chmodSync(secretPath, 0o600)
  } catch {
    // chmod is best-effort on platforms without POSIX permissions.
  }
  return secret
}



// Phase B3: the five pending-approval registries (pendingCodexApprovals,
// pendingKimiApprovals, pendingGeminiToolApprovals, pendingHostCommandApprovals,
// pendingMainApprovals) now live inside the ApprovalService instance
// constructed in whenReady. All previous `pending*Approvals.set(...)` call
// sites now call `approvalService.registerXxx(...)`; the unified
// `processAgentApprovalResponse` is now `approvalService.resolve(...)`.
const agenticSessionGrants = new Set<string>()
let activeCodexRunState: CodexRunState | null = null
const cliProviderProcesses = new Map<ProviderId, ChildProcess>()
const cliProviderAbortControllers = new Map<ProviderId, AbortController>()
function canonicalPath(value: string): string {
  return resolve(expandHomePath(value))
}

function canonicalExternalGrantPath(value: string): string | null {
  let cursor = canonicalPath(value)
  const missingSegments: string[] = []
  while (true) {
    try {
      const real = fsSync.realpathSync.native(cursor)
      return resolve(real, ...missingSegments)
    } catch {
      const parent = dirname(cursor)
      if (parent === cursor) return null
      missingSegments.unshift(basename(cursor))
      cursor = parent
    }
  }
}

function isSymlinkPath(value: string): boolean {
  try {
    return fsSync.lstatSync(value).isSymbolicLink()
  } catch {
    return false
  }
}

function chatScope(chat: Pick<ChatRecord, 'scope'> | null | undefined): ChatScope {
  return chat?.scope === 'global' ? 'global' : 'workspace'
}

function globalRunCwd(): string {
  return canonicalPath(app.getPath('home'))
}

// 1.0.5-EW17 — Isolated cwd for global-mode Gemini CLI runs.
//
// Gemini CLI does an aggressive workspace scan on startup: it
// shells out to ripgrep, and when ripgrep is missing it falls
// back to GrepTool, which walks the cwd recursively to build an
// initial file inventory. Pointing it at `$HOME` (what
// `globalRunCwd()` returns for global-mode runs) means scanning
// `~/Library`, `~/Documents`, `~/Pictures`, etc. — millions of
// files. In the maintainer's repro the scan didn't finish within 3 minutes
// and EW15's stuck-process detector fired the kill. The other
// CLIs (Codex, Claude SDK, Kimi) don't do a recursive workspace
// scan on startup, so they're unaffected by `$HOME` cwd.
//
// Fix: give Gemini a dedicated tiny directory in the TaskWraith user
// data folder. The scan completes instantly because the dir
// contains nothing the user cares about. File-system tool calls
// for global-mode Gemini already require explicit external path
// grants (resolved upstream), so isolating cwd doesn't reduce
// capability — if anything it improves the safety model because
// Gemini's "I can see all these files" mental baseline gets reset
// to "I see an empty workspace, I need tools to read user files".
function globalGeminiCwd(): string {
  const dir = join(app.getPath('userData'), 'global-gemini-cwd')
  try {
    fsSync.mkdirSync(dir, { recursive: true })
    // Stamp a marker file so the directory isn't truly empty —
    // some CLI heuristics treat "0 files" as a misconfiguration
    // and emit warnings. The marker is harmless and stable.
    const marker = join(dir, '.taskwraith-global-cwd')
    if (!fsSync.existsSync(marker)) {
      fsSync.writeFileSync(
        marker,
        'TaskWraith-managed isolated cwd for global-mode Gemini CLI runs. ' +
          'Do not delete or modify — recreated on demand if missing.\n'
      )
    }
  } catch {
    // If we can't create the dir (sandbox / permissions / disk
    // full), fall back to `$HOME` rather than crashing the run.
    // Worst case the user is back where they were before EW17.
    return globalRunCwd()
  }
  return canonicalPath(dir)
}

function requireGlobalChat(chatId: unknown, label = 'Global chat'): ChatRecord {
  const id = requireNonEmptyString(chatId, label)
  const chat = AppStore.getChat(id)
  if (!chat || chatScope(chat) !== 'global') {
    throw new Error(`${label} must be a saved global chat.`)
  }
  return chat
}

/** Persist the user turn the iOS composer sends BEFORE dispatching the
 * provider adapter. The desktop renderer normally appends the user
 * message + run record in App.tsx prior to `run-agent`; the remote
 * bridge skipped that step, so snapshots stayed stale even when the
 * Mac run completed successfully. */
/** Phone-renderable image previews. Built Mac-side from the decoded image
 * buffers because iOS can't read the Mac-local `imagePaths` — without a
 * shipped thumbnail the phone transcript can only show a count chip, so a
 * sent attachment looks like it vanished. ~256px longest edge, JPEG, size-
 * capped to stay inside the relay frame budget. Best-effort: an unrenderable
 * buffer is skipped, never thrown (the dispatch path must not fail on a
 * decorative preview). */
function buildBridgeImageThumbnails(
  buffers: Buffer[]
): Array<{ dataBase64: string; mimeType: string; width: number; height: number }> {
  const thumbs: Array<{ dataBase64: string; mimeType: string; width: number; height: number }> = []
  for (const buf of buffers.slice(0, 2)) {
    try {
      const img = nativeImage.createFromBuffer(buf)
      if (img.isEmpty()) continue
      const { width, height } = img.getSize()
      if (!width || !height) continue
      const maxEdge = 256
      const longest = Math.max(width, height)
      const scale = longest > maxEdge ? maxEdge / longest : 1
      const tw = Math.max(1, Math.round(width * scale))
      const th = Math.max(1, Math.round(height * scale))
      const resized = scale < 1 ? img.resize({ width: tw, height: th, quality: 'good' }) : img
      let quality = 70
      let jpeg = resized.toJPEG(quality)
      while (jpeg.length > 60_000 && quality > 30) {
        quality -= 15
        jpeg = resized.toJPEG(quality)
      }
      thumbs.push({
        dataBase64: jpeg.toString('base64'),
        mimeType: 'image/jpeg',
        width: tw,
        height: th
      })
    } catch {
      // Skip an image we can't decode/resize — the count chip still renders.
    }
  }
  return thumbs
}

// Shared audio engine for poster/waveform generation (offscreen Web Audio render).
// Lazy so the BrowserWindow machinery is touched only when a producer first needs a
// waveform. Distinct from the audio-tool engine instance but the same class.
let posterAudioEngine: ReturnType<typeof createNativeAudioEngine> | null = null
function getPosterAudioEngine(): ReturnType<typeof createNativeAudioEngine> {
  if (!posterAudioEngine) posterAudioEngine = createNativeAudioEngine()
  return posterAudioEngine
}

// Race a promise against a timer; resolve to `fallback` (never reject) on timeout.
// Used to bound poster generation so a hung decode/analyze can't stall a producer.
function withPosterTimeout<T>(promise: Promise<T>, ms: number, fallback: T): Promise<T> {
  return new Promise<T>((resolve) => {
    let settled = false
    const timer = setTimeout(() => {
      if (settled) return
      settled = true
      resolve(fallback)
    }, ms)
    promise.then(
      (value) => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        resolve(value)
      },
      () => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        resolve(fallback)
      }
    )
  })
}

// Downscale a decoded PNG/raster buffer to a small, size-capped JPEG poster. Mirrors
// buildBridgeImageThumbnails: ~320px longest edge, quality-reduction loop until the
// JPEG is under ~120KB (the 180KB iOS projection cap demands the poster stay small).
// Returns undefined on an undecodable/empty buffer — never throws.
const POSTER_MAX_EDGE = 320
const POSTER_MAX_BYTES = 120_000
function downscalePosterJpeg(buffer: Buffer): TranscriptMediaThumbnail | undefined {
  try {
    const img = nativeImage.createFromBuffer(buffer)
    if (img.isEmpty()) return undefined
    const { width, height } = img.getSize()
    if (!width || !height) return undefined
    const longest = Math.max(width, height)
    const scale = longest > POSTER_MAX_EDGE ? POSTER_MAX_EDGE / longest : 1
    const tw = Math.max(1, Math.round(width * scale))
    const th = Math.max(1, Math.round(height * scale))
    const resized = scale < 1 ? img.resize({ width: tw, height: th, quality: 'good' }) : img
    let quality = 70
    let jpeg = resized.toJPEG(quality)
    while (jpeg.length > POSTER_MAX_BYTES && quality > 30) {
      quality -= 15
      jpeg = resized.toJPEG(quality)
    }
    // If even q30 can't fit the cap, drop the poster rather than ship an oversized
    // blob that would blow the iOS projection budget.
    if (jpeg.length > POSTER_MAX_BYTES) return undefined
    return {
      dataBase64: jpeg.toString('base64'),
      mimeType: 'image/jpeg',
      width: tw,
      height: th
    }
  } catch {
    return undefined
  }
}

// Audio outputs above this are skipped: analyzeAudio base64s the WHOLE file into an
// offscreen page, so a big WAV would spike the heap. Posters are decorative — a card
// for a 40MB mix simply renders without a waveform.
const POSTER_AUDIO_MAX_BYTES = 24 * 1024 * 1024
// Outer guard so a single poster can never hang a producer for long.
const POSTER_TIMEOUT_MS = 12_000

// Best-effort poster/waveform for an already-written AV staging file. INJECTED into
// both the ffmpeg + VideoToolbox producers (the `generatePoster` dep). MUST be fully
// fail-tolerant: it NEVER throws and resolves to undefined on any error/timeout/empty
// result, so a producer always returns its ref (just with no poster), exactly as
// before this feature. Called BEFORE the producer removes the staging file.
//   - VIDEO: native VideoToolbox `video.decodeFrame` at t=0 (under mediaProcessLimiter,
//     the same encoder semaphore) → base64 PNG → downscaled, size-capped JPEG.
//   - AUDIO: the offscreen audio engine's analyzeAudio → waveform PNG → same downscale.
//     Skipped above POSTER_AUDIO_MAX_BYTES to avoid a heap spike.
async function generateAvPoster(
  outputPath: string,
  kind: 'audio' | 'video',
  mimeType: string,
  byteLength: number
): Promise<AvPosterResult | undefined> {
  try {
    return await withPosterTimeout(
      (async (): Promise<AvPosterResult | undefined> => {
        if (kind === 'video') {
          const daemon = bridgeDaemonRef
          if (!daemon) return undefined
          // Decode the first frame natively. Share the encoder semaphore so poster
          // decodes can't pile on top of N concurrent encodes.
          const decoded = await mediaProcessLimiter.run(() =>
            daemon.request<{
              pngBase64: string
              width: number
              height: number
              timestampSeconds: number
              codec: string
              usedHardware: boolean
            }>('video.decodeFrame', { inputPath: outputPath, timestampSeconds: 0 }, { timeoutMs: 30_000 })
          )
          if (!decoded?.pngBase64) return undefined
          const png = Buffer.from(decoded.pngBase64, 'base64')
          if (png.length === 0) return undefined
          const thumbnail = downscalePosterJpeg(png)
          // Video has no waveform envelope — thumbnail only.
          return thumbnail ? { thumbnail } : undefined
        }
        // AUDIO — render a waveform from the file's samples. Skip big files (heap).
        if (byteLength > POSTER_AUDIO_MAX_BYTES) return undefined
        let audioBuffer: Buffer
        try {
          audioBuffer = fsSync.readFileSync(outputPath)
        } catch {
          return undefined
        }
        if (audioBuffer.length === 0) return undefined
        // The SAME offscreen analysis pass paints the poster PNG AND hands back the
        // compact `peaks` envelope (harvested from the already-decoded channel-0
        // data — no second decode). Re-validate the page output before trusting it.
        const { png, meta } = await getPosterAudioEngine().analyzeAudio({
          dataBase64: audioBuffer.toString('base64'),
          mimeType,
          width: POSTER_MAX_EDGE,
          height: 80
        })
        const peaks = normalizeHarvestedPeaks(meta?.peaks)
        const thumbnail = png && png.length > 0 ? downscalePosterJpeg(png) : undefined
        // Return whichever of poster/peaks we got. Peaks can survive even if the
        // JPEG downscale fails (and vice-versa) — both are optional on the ref.
        if (!thumbnail && !peaks) return undefined
        const result: AvPosterResult = {}
        if (thumbnail) result.thumbnail = thumbnail
        if (peaks) result.peaks = peaks
        return result
      })(),
      POSTER_TIMEOUT_MS,
      undefined
    )
  } catch {
    // Defense-in-depth — withPosterTimeout already swallows rejections, but a sync
    // throw before the race (e.g. mediaProcessLimiter.run wiring) is caught here too.
    return undefined
  }
}

function prepareIosComposerPromptChat(args: {
  action: {
    threadId: string
    text: string
    provider: string
    approvalMode?: string
    model?: string
  }
  /** null = a scope-global chat (T72) — no workspace binding. */
  workspace: WorkspaceRecord | null
  imagePaths?: string[]
  imageThumbnails?: Array<{ dataBase64: string; mimeType: string; width?: number; height?: number }>
}): ChatRecord {
  const { action, workspace } = args
  const provider = assertProviderId(action.provider)
  const now = Date.now()
  const timestamp = new Date(now).toISOString()
  const prompt = action.text.trim()
  let chat = AppStore.getChat(action.threadId)
  if (!chat) {
    const title =
      prompt.length > 0
        ? prompt.length > 72
          ? `${prompt.slice(0, 69).trimEnd()}...`
          : prompt
        : 'New Chat'
    chat = {
      appChatId: action.threadId,
      scope: workspace ? 'workspace' : 'global',
      chatKind: 'single',
      provider,
      title,
      ...(workspace ? { workspaceId: workspace.id, workspacePath: workspace.path } : {}),
      createdAt: now,
      updatedAt: now,
      archived: false,
      messages: [],
      runs: [],
      ...(action.model ? { requestedModel: action.model } : {})
    }
  }
  const userMessage: ChatMessage = {
    id: `ios-user-${randomUUID()}`,
    role: 'user',
    content: prompt,
    timestamp,
    ...(args.imagePaths?.length || args.imageThumbnails?.length
      ? {
          metadata: {
            ...(args.imagePaths?.length ? { imagePaths: args.imagePaths } : {}),
            ...(args.imageThumbnails?.length
              ? { imageThumbnails: args.imageThumbnails }
              : {})
          }
        }
      : {})
  }
  const providerSwitched = provider !== chat.provider
  const withUserMessage: ChatRecord = {
    ...chat,
    ...(action.model ? { requestedModel: action.model } : {}),
    messages: [...(chat.messages || []), userMessage],
    updatedAt: now
  }
  // Slice B.1 — iOS provider-switch session hygiene. An iOS provider change
  // rides `providerOverride` on the send (no separate persist action), landing
  // here as `action.provider`. On a GENUINE switch of an existing thread, route
  // through the shared `applyProviderChange` so the old provider's linked
  // sessions are cleared — otherwise the next bridge run resumes the old
  // session under the new provider (see the resume-session read further down).
  // `withUserMessage` still holds the OLD provider (we haven't overwritten it),
  // so `providerChanged` fires correctly. A same-provider send keeps the live
  // session; a brand-new chat never switches (its provider was just set above).
  const updated: ChatRecord = providerSwitched
    ? applyProviderChange(withUserMessage, {
        provider,
        ...(action.model ? { providerMetadata: { selectedModelType: action.model } } : {})
      })
    : { ...withUserMessage, provider }
  AppStore.saveChat(updated)
  return updated
}

function validateChatWorkspaceIdentity(
  chatId: string | undefined,
  workspace: WorkspaceRecord | undefined
): void {
  if (!chatId) return
  const chat = AppStore.getChat(chatId)
  if (!chat) return
  if (chatScope(chat) === 'global') {
    throw new Error('Global chats cannot be used for workspace-scoped runs.')
  }
  if (workspace && chat.workspaceId && chat.workspaceId !== workspace.id) {
    // Legacy chats may reference their workspace by display name or path
    // instead of the uuid (see WorkspaceIdentity.ts) — resolve before
    // declaring a mismatch, or follow-up turns on those chats are rejected.
    const canonical = resolveCanonicalWorkspaceId(
      chat.workspaceId,
      AppStore.getWorkspaces(),
      canonicalPath
    )
    if (canonical !== workspace.id) {
      throw new Error('Chat workspace does not match the selected workspace.')
    }
  }
}

function sanitizeChatForSave(chat: ChatRecord): ChatRecord {
  const normalizedTitle = normalizeThreadTitle(chat.title, 'Untitled chat')
  const scope = chatScope(chat)
  if (scope === 'global') {
    const { workspaceId: _workspaceId, workspacePath: _workspacePath, ...rest } = chat
    return {
      ...rest,
      title: normalizedTitle,
      scope: 'global'
    }
  }
  if (!chat.workspacePath || !chat.workspaceId) {
    throw new Error('Workspace chat must include a workspace id and path.')
  }
  const workspace = findRegisteredWorkspace(chat.workspacePath)
  if (!workspace || workspace.id !== chat.workspaceId) {
    throw new Error('Chat workspace must be a registered TaskWraith workspace.')
  }
  return {
    ...chat,
    title: normalizedTitle,
    scope: 'workspace',
    workspaceId: workspace.id,
    workspacePath: canonicalPath(workspace.path)
  }
}

const RUN_ANALYST_MAX_TEXT = 900
const RUN_ANALYST_MAX_ITEMS = 16

function compactRunAnalystText(value: unknown, maxLength = RUN_ANALYST_MAX_TEXT): string {
  const text = String(value || '')
    .replace(/\s+/g, ' ')
    .trim()
  return text.length > maxLength ? `${text.slice(0, Math.max(0, maxLength - 1))}…` : text
}

function sanitizeRunAnalystSignals(value: unknown): RunAnalystSignal[] {
  if (!Array.isArray(value)) return []
  return value.slice(0, 8).map((item) => {
    const record = asRecord(item) || {}
    const tone = record.tone
    return {
      label: compactRunAnalystText(record.label, 80) || 'Signal',
      value: compactRunAnalystText(record.value, 120),
      ...(tone === 'good' || tone === 'warn' || tone === 'bad' || tone === 'neutral'
        ? { tone }
        : {})
    }
  })
}

function sanitizeRunAnalystRequest(input: unknown): RunAnalystRequest {
  const record = requireRecord(input, 'Run analyst request')
  const provider =
    typeof record.provider === 'string' && availableProviderIds().includes(record.provider as ProviderId)
      ? (record.provider as ProviderId)
      : undefined
  const timeline = Array.isArray(record.timeline)
    ? record.timeline.slice(0, RUN_ANALYST_MAX_ITEMS).map((item) => {
        const row = asRecord(item) || {}
        return {
          kind: compactRunAnalystText(row.kind, 80) as RunEventKind | string,
          summary: compactRunAnalystText(row.summary, 240),
          timestamp: compactRunAnalystText(row.timestamp, 80)
        }
      })
    : []
  return {
    runId: requireNonEmptyString(record.runId, 'Run id'),
    ...(provider ? { provider } : {}),
    chatTitle: compactRunAnalystText(record.chatTitle, 140),
    status: compactRunAnalystText(record.status, 80),
    startedAt: compactRunAnalystText(record.startedAt, 80),
    endedAt: compactRunAnalystText(record.endedAt, 80),
    promptPreview: compactRunAnalystText(record.promptPreview, 500),
    workspacePath: compactRunAnalystText(record.workspacePath, 500),
    touchedFiles: stringArray(record.touchedFiles).slice(0, RUN_ANALYST_MAX_ITEMS),
    warnings: stringArray(record.warnings).slice(0, RUN_ANALYST_MAX_ITEMS),
    countsByKind: asRecord(record.countsByKind) || {},
    timeline
  }
}

function normalizeRunAnalystResult(
  request: RunAnalystRequest,
  result: unknown,
  generatedAt: string
): RunAnalystSnapshot {
  const record = asRecord(result) || {}
  const status = record.status === 'error' || record.status === 'unavailable' ? record.status : 'ready'
  return {
    runId: request.runId,
    generatedAt,
    source: 'foundationModels',
    status,
    summary:
      compactRunAnalystText(record.summary, 1400) ||
      'Foundation Models returned no run summary.',
    risks: stringArray(record.risks).slice(0, 6),
    nextSteps: stringArray(record.nextSteps).slice(0, 6),
    signals: sanitizeRunAnalystSignals(record.signals),
    model: compactRunAnalystText(record.model, 120) || 'Apple Foundation Models',
    error: compactRunAnalystText(record.error, 500) || undefined
  }
}

function buildRunAnalystUnavailableSnapshot(
  request: RunAnalystRequest,
  reason: string
): RunAnalystSnapshot {
  return {
    runId: request.runId,
    generatedAt: new Date().toISOString(),
    source: 'foundationModels',
    status: 'unavailable',
    summary: 'Local Foundation Models analysis is unavailable for this run.',
    risks: [],
    nextSteps: ['Use the local deterministic summary in the Run rail.'],
    signals: [
      {
        label: 'Foundation Models',
        value: reason,
        tone: 'warn'
      }
    ],
    error: reason
  }
}

function assertSafeWorkspaceRoot(workspacePath: string): void {
  const normalized = canonicalPath(workspacePath)
  const root = parse(normalized).root
  if (normalized === root) {
    throw new Error('Filesystem roots cannot be registered as workspaces.')
  }
}

function findRegisteredWorkspace(workspacePath: string): WorkspaceRecord | undefined {
  const normalized = canonicalPath(workspacePath)
  return AppStore.getWorkspaces().find((workspace) => canonicalPath(workspace.path) === normalized)
}

function requireRegisteredWorkspace(workspacePath: string, label = 'Workspace'): string {
  const normalized = canonicalPath(requireNonEmptyString(workspacePath, label))
  assertSafeWorkspaceRoot(normalized)
  if (!findRegisteredWorkspace(normalized)) {
    throw new Error(`${label} must be selected through TaskWraith before it can be used.`)
  }
  return normalized
}

const {
  sanitizeScheduledTaskForSave,
  sanitizeScheduledTaskPatch,
  sanitizeWorkflowForSave,
  sanitizeWorkflowPatch,
  sanitizeWorkspaceBoardForSave,
  sanitizeWorkspaceBoardPatch,
  sanitizeWorkspaceBoardCardForSave,
  sanitizeWorkspaceBoardCardPatch,
  sanitizeRuntimeProfileForSave,
  sanitizeHandoffCardForSave,
  sanitizeHandoffCardPatch,
  sanitizeHandoffCardFilter,
  sanitizeSettingsPatch
} = createMainSanitizers({
  getSettings: () => AppStore.getSettings(),
  getScheduledTasks: () => AppStore.getScheduledTasks(),
  getWorkflowDefinitions: () => AppStore.getWorkflowDefinitions(),
  findRegisteredWorkspace,
  requireRegisteredWorkspace,
  canonicalPath,
  normalizeExternalPathGrants
})

function externalGrantSigningPayload(
  grant: Pick<
    ExternalPathGrant,
    'id' | 'provider' | 'path' | 'kind' | 'access' | 'duration' | 'createdAt'
  >
): string {
  return JSON.stringify({
    id: grant.id,
    provider: grant.provider,
    path: canonicalPath(grant.path),
    kind: grant.kind,
    access: grant.access,
    duration: grant.duration,
    createdAt: grant.createdAt
  })
}

function signExternalPathGrant(
  grant: Pick<
    ExternalPathGrant,
    'id' | 'provider' | 'path' | 'kind' | 'access' | 'duration' | 'createdAt'
  >
): string {
  return createHmac('sha256', externalGrantSigningSecret)
    .update(externalGrantSigningPayload(grant))
    .digest('hex')
}

function issueExternalPathGrant(
  grant: Omit<ExternalPathGrant, 'issuedBy' | 'signature'>
): ExternalPathGrant {
  const canonicalGrantPath = canonicalExternalGrantPath(grant.path) || canonicalPath(grant.path)
  const normalizedGrant: ExternalPathGrant = {
    ...grant,
    path: canonicalGrantPath,
    issuedBy: 'main',
    signature: ''
  }
  normalizedGrant.signature = signExternalPathGrant(normalizedGrant)
  return normalizedGrant
}

const RUN_NATIVE_IMAGE_ATTACHMENT_EXT = /\.(png|jpe?g|gif|webp|bmp|heic|avif|tiff|tif|svg|jfif)(\?.*)?$/i
let pdfAttachmentRenderCachePruned = false

function runAttachmentPath(rawPath: unknown): string | null {
  if (typeof rawPath !== 'string') return null
  const trimmed = rawPath.trim()
  if (!trimmed) return null
  if (trimmed.startsWith('file://')) {
    try {
      const filePath = fileURLToPath(trimmed)
      return isAbsolute(filePath) ? filePath : null
    } catch {
      return null
    }
  }
  return isAbsolute(trimmed) ? trimmed : null
}

function isNativeImageRunAttachment(rawPath: unknown): boolean {
  const attachmentPath = runAttachmentPath(rawPath)
  return attachmentPath ? RUN_NATIVE_IMAGE_ATTACHMENT_EXT.test(attachmentPath) : false
}

function prunePdfAttachmentRenderCacheOnce(): void {
  if (pdfAttachmentRenderCachePruned) return
  pdfAttachmentRenderCachePruned = true
  void prunePdfAttachmentRenderCache(getPdfAttachmentRenderCacheDir()).catch(() => undefined)
}

function compactPdfRenderedPageAttachment(page: PdfRenderedPageAttachment): {
  id: string
  path: string
  name: string
} {
  return { id: page.id, path: page.path, name: page.name }
}

async function renderPdfPagesForAttachments(
  attachments: PdfAttachmentLike[]
): Promise<PdfRenderedPageAttachment[]> {
  if (!attachments.some((attachment) => isPdfAttachmentPath(attachment?.path))) return []
  prunePdfAttachmentRenderCacheOnce()
  const result = await renderPdfAttachmentPages(attachments, {
    cacheDir: getPdfAttachmentRenderCacheDir()
  })
  for (const skipped of result.skipped) {
    console.warn(
      `[pdf-attachments] skipped ${skipped.name || skipped.path}: ${skipped.reason}`
    )
  }
  return result.rendered
}

async function expandPdfAttachmentsForDispatch<T extends PdfAttachmentLike>(
  attachments: T[]
): Promise<Array<T | { id: string; path: string; name: string }>> {
  const rendered = await renderPdfPagesForAttachments(attachments)
  if (rendered.length === 0) return attachments
  return [...attachments, ...rendered.map(compactPdfRenderedPageAttachment)]
}

async function expandPdfImagePathsForPayload(payload: AgentRunPayload): Promise<void> {
  const imagePaths = Array.isArray(payload.imagePaths) ? payload.imagePaths : []
  const pdfPaths = imagePaths.filter((imagePath) => isPdfAttachmentPath(imagePath))
  if (pdfPaths.length === 0) return
  const rendered = await renderPdfPagesForAttachments(
    pdfPaths.map((pdfPath, index) => ({
      id: `pdf-image-path-${index + 1}`,
      path: pdfPath,
      name: basename(runAttachmentPath(pdfPath) || pdfPath)
    }))
  )
  const nextPaths = [
    ...imagePaths.filter((imagePath) => !isPdfAttachmentPath(imagePath)),
    ...rendered.map((page) => page.path)
  ]
  const seen = new Set<string>()
  payload.imagePaths = nextPaths.filter((imagePath) => {
    const key = imagePath.trim()
    if (!key || seen.has(key)) return false
    seen.add(key)
    return true
  })
}

function isPathInsideRoot(rootPath: string | undefined, candidatePath: string): boolean {
  if (!rootPath) return false
  const root = resolve(rootPath)
  const candidate = resolve(candidatePath)
  const rel = relative(root, candidate)
  return rel === '' || (Boolean(rel) && !rel.startsWith('..') && !isAbsolute(rel))
}

function ensembleExternalGrantProviders(chat: ChatRecord): ProviderId[] {
  if (chat.chatKind !== 'ensemble' || !chat.ensemble?.participants?.length) return []
  const seen = new Set<ProviderId>()
  const providers: ProviderId[] = []
  for (const participant of chat.ensemble.participants) {
    if (!participant.enabled) continue
    if (!isExternalPathGrantDispatchProvider(participant.provider)) continue
    if (seen.has(participant.provider)) continue
    seen.add(participant.provider)
    providers.push(participant.provider)
  }
  return providers
}

function issueRunScopedExternalGrantsForNonImageAttachments(
  chat: ChatRecord,
  attachments: Array<{ path?: string; name?: string }>,
  existingGrants: ExternalPathGrant[] = []
): ExternalPathGrant[] {
  if (chat.scope === 'global' || !chat.workspacePath || attachments.length === 0) return []
  const providers = ensembleExternalGrantProviders(chat)
  if (providers.length === 0) return []
  const seen = new Set(
    normalizeExternalPathGrants(existingGrants).map((grant) => `${grant.provider}:${grant.path}`)
  )
  const grants: ExternalPathGrant[] = []
  const now = Date.now()
  for (const attachment of attachments) {
    const attachmentPath = runAttachmentPath(attachment?.path)
    if (!attachmentPath || isNativeImageRunAttachment(attachmentPath)) continue
    if (isPathInsideRoot(chat.workspacePath, attachmentPath)) continue
    let kind: ExternalPathGrant['kind'] = 'file'
    try {
      const stat = fsSync.statSync(attachmentPath)
      kind = stat.isDirectory() ? 'directory' : 'file'
    } catch {
      continue
    }
    for (const provider of providers) {
      const grant = issueExternalPathGrant({
        id: `attachment-${now}-${provider}-${randomBytes(4).toString('hex')}`,
        provider,
        workspaceId: chat.workspaceId,
        chatId: chat.appChatId,
        path: attachmentPath,
        kind,
        access: 'read',
        duration: 'thisRun',
        createdAt: new Date(now).toISOString()
      })
      const key = `${grant.provider}:${grant.path}`
      if (seen.has(key)) continue
      seen.add(key)
      grants.push(grant)
    }
  }
  return grants
}

function isMainIssuedExternalPathGrant(grant: ExternalPathGrant): boolean {
  if (!grant || grant.issuedBy !== 'main' || typeof grant.signature !== 'string') return false
  const expected = Buffer.from(signExternalPathGrant(grant), 'hex')
  const actual = Buffer.from(grant.signature, 'hex')
  return expected.length === actual.length && timingSafeEqual(expected, actual)
}

// Run permission posture provenance. Mirrors the external-path-grant HMAC
// above but binds `{ approvalMode, workflowMode, effectivePermissions }`
// so only a main-side producer can mint a permissive run posture. Every
// trusted producer (ComposerService, EnsembleOrchestrator, sub-thread
// delegation, SoloChatWakeupService) stamps `effectivePermissionsSignature`
// via `signRunPosture`; `normalizeAgentRunPayload` verifies + downgrades.
// See src/main/RunPermissionPosture.ts.
function signRunPosture(
  approvalMode: string | null | undefined,
  effectivePermissions: EffectiveRunPermissions | null | undefined,
  context?: RunPermissionPostureContext | null
): string {
  return signRunPermissionPosture(
    externalGrantSigningSecret,
    approvalMode,
    effectivePermissions,
    context
  )
}

function verifyRunPosture(
  approvalMode: string | null | undefined,
  effectivePermissions: EffectiveRunPermissions | null | undefined,
  signature: string | null | undefined,
  context?: RunPermissionPostureContext | null
): boolean {
  return verifyRunPermissionPosture(
    externalGrantSigningSecret,
    approvalMode,
    effectivePermissions,
    signature,
    context
  )
}

// ── P2: unattended-elevation ack provenance ─────────────────────────────────
// The ack lifts an UNATTENDED (scheduled) workflow run above the forced-'plan'
// clamp. It is a plain JSON blob on the WorkflowDefinition (forgeable by a local
// workflows.json edit), so it is HMAC-bound — same secret + path canonicalization
// as the external-path-grant signer — and RE-VERIFIED here at every dispatch.
function signWorkflowUnattendedElevation(
  workflowId: string,
  workspacePath: string,
  level: UnattendedElevationLevel,
  acknowledgedApprovalMode: string
): string {
  return signUnattendedElevation(externalGrantSigningSecret, {
    workflowId,
    workspacePath: canonicalPath(workspacePath),
    level,
    acknowledgedApprovalMode
  })
}

// Resolve a VERIFIED, CURRENT elevation for a scheduled occurrence. Both gates
// fail-closed: the HMAC must verify AND isUnattendedElevationAckCurrent must hold
// (template.approvalMode unchanged since the ack + the level still authorizes it).
// Returns null on any miss → the unattended run stays clamped to 'plan'. Injected
// into ComposerService + reused by the ensemble dispatch handler.
function resolveUnattendedElevation(
  scheduledTaskId: string
): { ack: UnattendedElevationAck; templateApprovalMode: string } | null {
  const task = AppStore.getScheduledTasks().find((t) => t.id === scheduledTaskId)
  if (!task?.workflowId) return null
  const wf = AppStore.getWorkflowDefinition(task.workflowId)
  if (!wf) return null
  const ack = wf.unattendedElevation
  if (!ack) return null
  const verified = verifyUnattendedElevation(
    externalGrantSigningSecret,
    {
      workflowId: wf.id,
      workspacePath: canonicalPath(wf.workspacePath),
      level: ack.level,
      acknowledgedApprovalMode: ack.acknowledgedApprovalMode
    },
    ack.signature
  )
  if (!verified) return null
  if (!isUnattendedElevationAckCurrent(ack, wf.template.approvalMode)) return null
  return { ack, templateApprovalMode: wf.template.approvalMode }
}

function buildScheduledTaskPostureForRecord(
  task: Pick<
    ScheduledTask,
    | 'id'
    | 'provider'
    | 'workspacePath'
    | 'chatId'
    | 'prompt'
    | 'approvalMode'
    | 'workflowMode'
    | 'selectedModelType'
    | 'customModel'
    | 'runtimeProfileId'
  >
) {
  return buildScheduledTaskPermissionPosture({
    id: task.id,
    provider: task.provider,
    workspacePath: task.workspacePath,
    chatId: task.chatId,
    prompt: task.prompt,
    approvalMode: task.approvalMode,
    workflowMode: task.workflowMode,
    selectedModelType: task.selectedModelType,
    customModel: task.customModel,
    runtimeProfileId: task.runtimeProfileId,
    settings: AppStore.getSettings(),
    unattendedElevationAck: resolveUnattendedElevation(task.id)?.ack ?? null,
    signRunPermissionPosture: signRunPosture
  })
}

function scheduledTaskHasSignedPosture(task: ScheduledTask): boolean {
  return Boolean(
    task.permissionPosture?.signaturePresent &&
      task.permissionPosture.signature &&
      task.dispatchReceipt?.permissionPostureSignaturePresent
  )
}

function ensureScheduledTaskSignedPosture(task: ScheduledTask): ScheduledTask {
  if (scheduledTaskHasSignedPosture(task)) return task
  const permissionPosture = buildScheduledTaskPostureForRecord(task)
  return AppStore.updateScheduledTask(task.id, { permissionPosture }) || {
    ...task,
    permissionPosture
  }
}

function saveScheduledTaskWithSignedPosture(
  task: Parameters<typeof AppStore.saveScheduledTask>[0]
): ScheduledTask {
  const id = task.id || randomUUID()
  const draft = {
    ...task,
    id
  }
  return AppStore.saveScheduledTask({
    ...draft,
    permissionPosture: buildScheduledTaskPostureForRecord({
      id,
      provider: draft.provider,
      workspacePath: draft.workspacePath,
      chatId: draft.chatId,
      prompt: draft.prompt,
      approvalMode: draft.approvalMode,
      workflowMode: draft.workflowMode,
      selectedModelType: draft.selectedModelType,
      customModel: draft.customModel,
      runtimeProfileId: draft.runtimeProfileId
    })
  })
}

function permissionPostureSnapshotFromSession(
  session:
    | {
        runId?: string
        appChatId?: string
        provider?: ProviderId
        workspacePath?: string
        state?: unknown
      }
    | undefined
): RunPermissionPostureSnapshot | undefined {
  const state = session?.state
  if (!state || typeof state !== 'object' || Array.isArray(state)) return undefined
  const record = state as {
    approvalMode?: unknown
    workflowMode?: unknown
    runtimeProfileId?: unknown
    effectivePermissions?: unknown
    effectivePermissionsSignature?: unknown
    appRunId?: unknown
    appChatId?: unknown
    prompt?: unknown
    ensembleRun?: unknown
  }
  const effectivePermissions = isRecord(record.effectivePermissions)
    ? (record.effectivePermissions as unknown as EffectiveRunPermissions)
    : undefined
  const approvalMode = optionalString(record.approvalMode)
  if (!approvalMode && !effectivePermissions) return undefined
  return buildRunPermissionPostureSnapshot({
    approvalMode,
    workflowMode: record.workflowMode === 'plan' ? 'plan' : 'normal',
    effectivePermissions,
    signature: optionalString(record.effectivePermissionsSignature),
    context: {
      provider: session.provider,
      scope: session.workspacePath ? 'workspace' : 'global',
      appRunId: optionalString(record.appRunId) || optionalString(session.runId),
      appChatId: optionalString(record.appChatId) || optionalString(session.appChatId),
      prompt: typeof record.prompt === 'string' ? record.prompt : null,
      workflowMode: record.workflowMode === 'plan' ? 'plan' : 'normal',
      runtimeProfileId: optionalString(record.runtimeProfileId),
      ensembleParticipantId: isRecord(record.ensembleRun)
        ? optionalString(record.ensembleRun.participantId)
        : null,
      ensembleLaneId: isRecord(record.ensembleRun)
        ? optionalString(record.ensembleRun.laneId)
        : null
    }
  })
}

function mergePermissionPostureMetadata(
  metadata: Record<string, unknown> | undefined,
  permissionPosture: RunPermissionPostureSnapshot | undefined
): Record<string, unknown> | undefined {
  if (!permissionPosture) return metadata
  return {
    ...(metadata ?? {}),
    permissionPosture
  }
}

function persistRunPermissionPostureOnChatRun(session: {
  runId: string
  appChatId?: string
  state?: unknown
  provider?: ProviderId
  workspacePath?: string
}): void {
  if (!session.appChatId) return
  const permissionPosture = permissionPostureSnapshotFromSession(session)
  if (!permissionPosture) return
  const chat = AppStore.getChat(session.appChatId)
  if (!chat?.runs?.length) return
  const runIndex = chat.runs.findIndex((run) => run.runId === session.runId)
  if (runIndex < 0) return
  const existingRun = chat.runs[runIndex]
  if (
    existingRun.permissionPosture?.postureHash === permissionPosture.postureHash &&
    existingRun.permissionPosture?.signature === permissionPosture.signature
  ) {
    return
  }
  const runs = [...chat.runs]
  runs[runIndex] = {
    ...existingRun,
    permissionPosture,
    approvalMode: existingRun.approvalMode || permissionPosture.approvalMode,
    workflowMode: existingRun.workflowMode || permissionPosture.workflowMode
  }
  const updated = {
    ...chat,
    runs,
    updatedAt: Date.now()
  }
  AppStore.saveChat(updated)
  broadcastChatUpdated(updated)
}

/**
 * Explicit dependencies for `normalizeAgentRunPayload` — the universal
 * run-dispatch trust boundary (M3-1a seam-first slice per
 * `design-next-extraction-spec`). Every field below closes over
 * index.ts-scoped runtime state (the external-grant signing secret, the
 * AppStore singleton, Electron paths, or fs realpath); injecting them makes
 * the normalizer independently unit-testable without a full Electron +
 * AppStore bootstrap and lets the eventual `run/AgentRunNormalizer.ts` module
 * (M3-1b) consume the secret ONLY via the `verifyRunPosture` /
 * `normalizeExternalPathGrants` / `isMainIssuedExternalPathGrant` closures —
 * never by re-reading it. Pattern mirrors the landed `RunCoordinatorDeps`.
 * Body stays inline this slice; zero behaviour change (each dep IS the exact
 * function the body previously referenced directly).
 */
async function ensureProviderRunPreflight(
  sender: Electron.WebContents,
  payload: AgentRunPayload
): Promise<boolean> {
  const route = routeWithRunId(payload.provider, payload)
  payload.appRunId = route.appRunId
  if (payload.scope === 'global') {
    try {
      requireGlobalChat(payload.appChatId, 'Run global chat')
      payload.workspace = globalRunCwd()
    } catch (error) {
      sendAgentCompatError(
        sender,
        payload.provider,
        error instanceof Error ? error.message : String(error),
        route
      )
      sendAgentCompatExit(sender, payload.provider, -1, route)
      return false
    }
  } else {
    try {
      const registeredWorkspace = requireRegisteredWorkspace(payload.workspace || '')
      const workspaceRecord = findRegisteredWorkspace(registeredWorkspace)
      validateChatWorkspaceIdentity(payload.appChatId, workspaceRecord)
      payload.workspace = await resolveRuntimeWorktreeWorkspace(payload, registeredWorkspace)
    } catch (error) {
      sendAgentCompatError(
        sender,
        payload.provider,
        error instanceof Error ? error.message : String(error),
        route
      )
      sendAgentCompatExit(sender, payload.provider, -1, route)
      return false
    }
  }

  if (!(await ensureWorkspaceTrustForRun(sender, payload))) {
    return false
  }

  const adapter = providerAdapters.require(payload.provider)
  const contract = await adapter.getCapabilityContract({
    workspacePath: payload.workspace,
    approvalMode: payload.approvalMode
  })
  const preflight = providerPreflightService.evaluate(
    {
      provider: payload.provider,
      workspacePath: payload.workspace,
      approvalMode: payload.approvalMode,
      model: payload.model,
      previewModelAccessProven: await previewModelAccessProvenForPayload(payload)
    },
    contract,
    adapter
  )
  if (preflight.state === 'ready') {
    return true
  }
  sendAgentCompatError(sender, payload.provider, preflight.reason, route)
  sendAgentCompatExit(sender, payload.provider, -1, route)
  return false
}

async function resolveRuntimeWorktreeWorkspace(
  payload: AgentRunPayload,
  registeredWorkspace: string
): Promise<string> {
  const intent = payload.runtimeWorktree
  if (!intent?.requested) return registeredWorkspace
  if (intent.status !== 'selected' || !intent.effectiveWorkspacePath) {
    const profile = intent.profileName ? ` (${intent.profileName})` : ''
    throw new Error(
      `Runtime profile${profile} requires an isolated worktree. Create or select one from Branch & worktree before running.`
    )
  }
  const baseWorkspace = requireRegisteredWorkspace(
    intent.baseWorkspacePath || registeredWorkspace,
    'Base workspace'
  )
  const targetPath = canonicalPath(requireNonEmptyString(intent.effectiveWorkspacePath, 'Worktree'))
  const list = await new GitService().listWorktrees(baseWorkspace)
  if (!list.ok) {
    throw new Error(list.error || 'Could not list linked git worktrees.')
  }
  const linked = list.data.worktrees.some(
    (worktree) => canonicalPath(worktree.path) === targetPath
  )
  if (!linked) {
    throw new Error('Selected worktree is not linked to the registered workspace repository.')
  }
  payload.runtimeWorktree = {
    ...intent,
    baseWorkspacePath: baseWorkspace,
    effectiveWorkspacePath: targetPath,
    status: 'selected'
  }
  return targetPath
}

async function previewModelAccessProvenForPayload(payload: AgentRunPayload): Promise<boolean> {
  const model = typeof payload.model === 'string' ? payload.model.trim() : ''
  if (!isPreviewRiskModel(payload.provider, model)) return false
  if (previewModelAccessFlagEnabledForProvider(payload.provider, process.env)) return true
  if (payload.provider !== 'codex') return false
  try {
    const client = getCodexClient(payload.runtimeProfile)
    await client.ensureStarted(app.getVersion())
    const response: any = await client.request('model/list', {}, 15_000)
    const models = Array.isArray(response?.data) ? response.data : []
    return models.some((entry: any) => entry && entry.hidden !== true && entry.id === model)
  } catch {
    return false
  }
}

function normalizeCodexDefaultModelRows<T extends { id?: string; isDefault?: boolean; disabled?: boolean }>(
  models: T[]
): T[] {
  const hasGpt55 = models.some((model) => model.id === 'gpt-5.5' && model.disabled !== true)
  const normalized = models
    .map((model) => ({
      ...model,
      isDefault: hasGpt55 ? model.id === 'gpt-5.5' : Boolean(model.isDefault && model.disabled !== true)
    }))
    .sort((a, b) => {
      if (a.id === 'gpt-5.5') return -1
      if (b.id === 'gpt-5.5') return 1
      return 0
    })
  return normalized as T[]
}


