function collectCurrentUserMcpBlockedServers(
  settings: AppSettings = AppStore.getSettings()
): UserMcpLaunchPolicyDecision[] {
  const allowlistPolicy = managedUserMcpLaunchAllowlistPolicy?.()
  if (!allowlistPolicy) return []
  const blocked: UserMcpLaunchPolicyDecision[] = []
  buildUserMcpLaunchServers(settings.userMcpServers, {
    supportedTransports: ['stdio', 'http', 'sse'],
    allowlistPolicy,
    validatePluginProvenance: validateUserMcpPluginProvenance,
    // Do not decrypt extension secrets for diagnostics/audit snapshots; the
    // allowlist has already evaluated secret ref names before resolution.
    resolveSecretValues: (refs) =>
      refs.map((ref) => ({
        ref,
        status: 'ok',
        value: '[redacted]'
      })),
    onBlocked: (decision) => blocked.push(decision)
  })
  return blocked
}

function normalizeProductAuditBundleFilter(
  filter?: ProductAuditBundleFilter
): ProductAuditBundleFilter {
  const normalized: ProductAuditBundleFilter = {}
  if (typeof filter?.workspaceId === 'string' && filter.workspaceId.trim()) {
    normalized.workspaceId = filter.workspaceId.trim()
  }
  if (typeof filter?.workspacePath === 'string' && filter.workspacePath.trim()) {
    normalized.workspacePath = filter.workspacePath.trim()
  }
  if (typeof filter?.chatId === 'string' && filter.chatId.trim()) {
    normalized.chatId = filter.chatId.trim()
  }
  if (typeof filter?.runId === 'string' && filter.runId.trim()) {
    normalized.runId = filter.runId.trim()
  }
  return normalized
}

function completeProductAuditBundleFilter(filter: ProductAuditBundleFilter): ProductAuditBundleFilter {
  const completed = { ...filter }
  if (completed.chatId) {
    const chat = AppStore.getChat(completed.chatId)
    if (chat?.workspaceId && !completed.workspaceId) completed.workspaceId = chat.workspaceId
    if (chat?.workspacePath && !completed.workspacePath) completed.workspacePath = chat.workspacePath
  }
  if (!completed.workspaceId && completed.workspacePath) {
    const workspace = AppStore.getWorkspaces().find(
      (candidate) => candidate.path === completed.workspacePath
    )
    if (workspace?.id) completed.workspaceId = workspace.id
  }
  return completed
}

function listAuditBundleRunEvents(filter: ProductAuditBundleFilter) {
  if (filter.runId) {
    return AppStore.getRunEvents({ runId: filter.runId })
  }
  if (filter.chatId) {
    const chat = AppStore.getChat(filter.chatId)
    const runIds = Array.from(
      new Set((chat?.runs ?? []).map((run) => run.runId).filter((id): id is string => Boolean(id)))
    )
    return runIds.flatMap((runId) => AppStore.getRunEvents({ runId }))
  }
  return AppStore.getRunEvents(filter.workspaceId ? { workspaceId: filter.workspaceId } : {})
}

function purgeExternalPublishAuditRetention(
  request: AuditRetentionPurgeRequest = {}
): AuditRetentionSurfacePurgeCounts {
  const ledger = getExternalPublishReceiptLedger()
  if (!ledger) return { scanned: 0, retained: 0, deleted: 0 }
  const policy = request.policy || AppStore.getSettings().auditRetention || {}
  const enabled = policy.enabled === true
  const dryRun = request.dryRun !== false || !enabled
  const days = Number(policy.maxAgeDays?.externalPublish)
  const clampedDays = Number.isFinite(days) && days > 0 ? Math.min(3650, Math.floor(days)) : 365
  const nowMs =
    typeof request.now === 'string' && Number.isFinite(Date.parse(request.now))
      ? Date.parse(request.now)
      : Date.now()
  const cutoffMs = enabled ? nowMs - clampedDays * 24 * 60 * 60 * 1000 : null
  return ledger.purgeOlderThan(cutoffMs, { dryRun })
}

function purgeProductAuditRetention(request: AuditRetentionPurgeRequest = {}) {
  const externalPublish = purgeExternalPublishAuditRetention(request)
  return AppStore.purgeAuditRetentionEvidence(request, { externalPublish })
}

function signProductAuditBundleSnapshot(snapshot: ProductAuditBundleSnapshot): ProductAuditBundleSnapshot {
  const signer = new AuditBundleSigningKeyStore(
    join(app.getPath('userData'), 'audit-bundle-signing-key.json'),
    safeStorage,
    (line) => console.warn(line)
  ).loadOrCreate()
  if (!signer) return snapshot
  return signAuditBundleSnapshot(snapshot, {
    keyId: signer.keyId,
    publicKeyDerBase64: signer.publicKeyDerBase64,
    signPayload: signer.signPayload
  })
}

async function buildCurrentAuditBundleSnapshot(request: ProductAuditBundleExportRequest = {}) {
  const filter = completeProductAuditBundleFilter(normalizeProductAuditBundleFilter(request.filter))
  const settings = AppStore.getSettings()
  const userMcpBlockedServers = collectCurrentUserMcpBlockedServers(settings)
  const snapshot = buildAuditBundleSnapshot({
    filter,
    approvalLedger: AppStore.getApprovalLedger({
      workspaceId: filter.workspaceId,
      chatId: filter.chatId,
      runId: filter.runId
    }),
    runEvents: listAuditBundleRunEvents(filter),
    workspaceChanges: AppStore.getWorkspaceChangeSets(filter),
    auditRuns: AppStore.getAuditRuns(filter.workspaceId),
    evidencePacks: AppStore.getEvidencePacks(filter.workspaceId),
    capabilityLedger: AppStore.getCapabilityLedgerSnapshot(filter.workspaceId),
    messageFeedbackReceipts: AppStore.getMessageFeedbackReceipts(filter),
    externalPublishReceipts: listExternalPublishReceipts(),
    auditBundleVerificationReceipts: AppStore.getAuditBundleVerificationReceipts(),
    auditRetentionPurgeReceipts: AppStore.getAuditRetentionPurgeReceipts(),
    userMcpBlockedServers
  })
  return signProductAuditBundleSnapshot(snapshot)
}

async function exportProductDiagnostics(
  requestedPath?: string
): Promise<ProductDiagnosticsExportResult> {
  try {
    const snapshot = await buildCurrentDiagnosticsSnapshot()
    let targetPath = requestedPath
    if (!targetPath) {
      if (!mainWindow) {
        throw new Error('No application window is available for diagnostics export.')
      }
      const result = await dialog.showSaveDialog(mainWindow, {
        title: 'Export TaskWraith Diagnostics',
        defaultPath: `TaskWraith-Diagnostics-${new Date().toISOString().replace(/[:.]/g, '-')}.json`,
        filters: [{ name: 'JSON diagnostics', extensions: ['json'] }]
      })
      if (result.canceled || !result.filePath) {
        return { ok: false, error: 'Diagnostics export cancelled.' }
      }
      targetPath = result.filePath
    }
    await fs.writeFile(targetPath, serializeDiagnosticsSnapshot(snapshot), 'utf8')
    return { ok: true, path: targetPath, snapshot }
  } catch (error) {
    recordProductCrash({
      source: 'main',
      severity: 'warning',
      name: error instanceof Error ? error.name : 'DiagnosticsExportError',
      message: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined
    })
    return { ok: false, error: error instanceof Error ? error.message : String(error) }
  }
}

